  'tool3-pro2' => 'Օգտագործողները ընտրում են սեղմման մակարդակները վերահսկվող ելքային չափի համար',
  'tool3-pro3' => 'Նույնքան լավ է աշխատում աշխատասեղանի կամ սմարթֆոնի բրաուզերների վրա',
  'tool3-con1' => 'Սահմանափակ անվճար օգտագործումներ մինչև վճարովի պլանի պահանջի հայտնվելը',
  'tool3-con2' => 'Օգտագործողները պետք է մուտք գործեն Adobe ID-ով, որը լրացուցիչ քայլեր է ձեռնարկում',
  'tool3-con3' => 'Պրեմիում գործառույթների համար գներն ավելի բարձր են, քան շատ այլընտրանքներ',
  'tool4-heading' => 'PDF լցոնիչ',
  'tool4-para' => 'PDFFiller-ը բազմաթիվ այլ խմբագրման գործիքների շարքում ապահովում է առցանց PDF կոմպրեսոր: Օգտատերերը կարող են ֆայլեր վերբեռնել և այնուհետև օգտագործել սեղմման տարբերակը խմբագրի ներսում: Պլատֆորմը ներառում է նաև PDF խմբագրման, ստորագրման և փոխակերպման գործառույթներ:',
  'tool4-pro1' => 'Համատեղում է սեղմումը խմբագրման և ստորագրման գործիքների հետ մեկ տեղում',
  'tool4-pro2' => 'Ինտուիտիվ ինտերֆեյսը օգտվողների համար հեշտացնում է փաստաթղթերի կառավարումը',
  'tool4-pro3' => 'Առցանց մուտք նշանակում է, որ ծրագրաշարի տեղադրում չի պահանջվում',
  'tool4-con1' => 'Օգտագործողները հաճախ պետք է մուտք գործեն, ինչը դանդաղեցնում է գործընթացը',
  'tool4-con2' => 'Որոշ գործառույթներ պահանջում են վճարովի բաժանորդագրություն՝ փոփոխությունները պահելու համար',
  'tool4-con3' => 'Սեղմման արդյունքը կարող է լինել ոչ այնքան փոքր, որքան հատուկ գործիքները',
  'tool5-heading' => '5. PDF24 գործիքներ',
  'tool5-para' => 'PDF24 Tools-ն առաջարկում է զննարկչի վրա հիմնված PDF կոմպրեսորային գործիք՝ PDF-ի սահուն սեղմման համար: Օգտագործողները կարող են թողնել մեկ կամ մի քանի PDF ֆայլ և արագ ընտրել սեղմման մակարդակ: Կայքը նաև պարունակում է բազմաթիվ անվճար ֆայլային գործիքներ PDF սեղմումից դուրս:',
  'tool5-pro1' => 'Աջակցում է մինչև տասը PDF ֆայլ մեկ սեղմման նստաշրջանի համար',
  'tool5-pro2' => 'Օգտագործողները ընտրում են թեթև, միջին կամ բարձր սեղմման կարգավորումներ',
  'tool5-pro3' => 'Ամբողջովին աշխատում է վեբ բրաուզերում՝ սարքի գաղտնիության համար',
  'tool5-con1' => 'Սեղմման տարբերակներն ավելի հիմնական են, քան որոշ առաջադեմ գործիքներ',
  'tool5-con2' => 'Ինտերֆեյսը ավելի քիչ ժամանակակից է թվում՝ համեմատած լավագույն կոմերցիոն ծառայությունների հետ',
  'tool5-con3' => 'Երբեմն կարող են հայտնվել գովազդներ, որոնք շեղում են առաջադրանքից',
  'comparison-intro' => 'Ահա վերը նշված գործիքների համառոտ համեմատությունը:',
  'table-col1' => 'Գործիքի անվանումը',
