  'table-row5-col5' => 'Ոչ',
  'security-tips-heading' => 'Անվտանգության նկատառումներ և սեղմման խորհուրդներ',
  'security-tips-intro' => 'Հետևյալ խորհուրդները կապահովեն հարթ և ապահով սեղմումներ։',
  'tip1-heading' => 'Ֆայլերի սեղմման անվտանգություն',
  'tip1-para' => 'Առցանց PDF սեղմումը պահանջում է ուշադրություն, թե ինչպես են գործիքներն ապահով կերպով վարում վերբեռնված փաստաթղթերը: Վստահելի հարթակները ֆայլերը մշակում են պաշտպանված կապերի և վերահսկվող սերվերային միջավայրերի միջոցով: Օգտագործողները պետք է ընտրեն այնպիսի ծառայություններ, որոնք հստակ բացատրում են սեղմման հետ աշխատելը և փաստաթղթերի անվտանգությունը:',
  'tip2-heading' => 'Վերբեռնված ֆայլերի ավտոմատ ջնջում',
  'tip2-para' => 'Ավտոմատ ջնջումը սերվերներից հեռացնում է սեղմված ֆայլերը պահպանման կարճ ժամանակահատվածներից հետո: Այս հատկությունը նվազեցնում է ազդեցության ռիսկերը և սահմանափակում պահված փաստաթղթերի չարտոնված մուտքը: Ջնջման ժամանակացույցերի մաքրումը օգնում է օգտվողներին վստահորեն վստահել առցանց սեղմման հարթակներին:',
  'tip3-heading' => 'Ընտրեք սեղմման ճիշտ մակարդակը',
  'tip3-para' => 'Հավասարակշռված սեղմումը պահպանում է ընթեռնելիությունը՝ միաժամանակ արդյունավետորեն նվազեցնելով ֆայլի չափը: Միջին սեղմումը համապատասխանում է պատկերի համար ծանր փաստաթղթերին, ինչպիսիք են սկանավորված հաշվետվությունները կամ բրոշյուրները: Զգույշ ընտրությունը կանխում է որակի անհարկի կորուստը բազմակի համօգտագործման ժամանակ:',
  'tip4-heading' => 'Պատրաստեք ֆայլերը սեղմումից առաջ',
  'tip4-para' => 'Չօգտագործված էջերի հեռացումը զգալիորեն նվազեցնում է ֆայլի վերջնական չափը: Բարձր լուծաչափով պատկերները օգուտ են ստանում չափափոխելուց՝ նախքան առցանց գործիքներ վերբեռնելը: Մաքուր փաստաթղթերը սեղմվում են ավելի արդյունավետ և ապահովում են հետևողական արդյունքներ:',
  'tip5-heading' => 'Խուսափեք մի քանի սեղմման ցիկլերից',
  'tip5-para' => 'Կրկնվող սեղմումը աստիճանաբար նվազեցնում է տեքստի հստակությունը և պատկերի հստակությունը: Օգտատերերը պետք է պահպանեն բնօրինակ ֆայլերը ապահով կերպով պահված ցանկացած առցանց մշակումից առաջ: Մեկ քայլով սեղմումը պահպանում է որակը և ապահովում փաստաթղթերի հուսալի թողարկում:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-para1' => 'PDF սեղմումը նվազեցնում է ֆայլի չափը և բարելավում է համօգտագործման և պահպանման արագությունը սարքերում: Առցանց PDF սեղմման գործիքները գրավում են օգտվողներին, քանի որ բրաուզերի գործիքները ծրագրային ապահովման տեղադրման կարիք չունեն: Հանրաճանաչ ծառայություններն առաջարկում են արագ արդյունքներ, պարզ միջերեսներ և աջակցում են բազմաթիվ հարթակներ:',
  'conclusion-para2' => 'Սեղմման գործիքները մշակման ընթացքում վերլուծում են փաստաթղթերը, պատկերները, տառատեսակները և չօգտագործված տարրերը: Պատկերի օպտիմիզացումը և խելացի մաքրումը օգնում են պահպանել որակը՝ միաժամանակ նվազեցնելով ընդհանուր չափը: Վստահելի հարթակները պաշտպանում են ֆայլերը գաղտնագրման և ավտոմատ ջնջման հստակ քաղաքականության միջոցով:',
  'conclusion-para3' => 'Օգտատերերը ավելի լավ արդյունքներ են ստանում՝ ընտրելով սեղմման համապատասխան մակարդակներ՝ ֆայլեր ներբեռնելուց առաջ: Պատրաստված փաստաթղթերը արդյունավետորեն սեղմվում են, երբ օգտվողները հեռացնում են չօգտագործված էջերը, պատկերները և տառատեսակները: Մեկ քայլով սեղմումը պահպանում է հստակությունը և ապահովում է հուսալի փոխանակում աշխատանքային միջավայրում:',
  'faqs-heading' => 'ՀՏՀ-ներ',
  'faq1-question' => 'Անվտանգ է արդյոք առցանց սեղմումը:',
  'faq1-answer' => 'Առցանց սեղմումը մնում է անվտանգ, երբ օգտվողներն ընտրում են հեղինակավոր հարթակներ՝ հստակ անվտանգության քաղաքականությամբ: Վստահելի գործիքներն օգտագործում են անվտանգ կապեր և վերահսկվող սերվերներ ֆայլերի մշակման ընթացքում: Օգտագործողները պետք է խուսափեն անհայտ կայքերից՝ զգայուն փաստաթղթերով աշխատելիս:',
  'faq2-question' => 'Որքա՞ն է հնարավոր չափի կրճատումը:',
  'faq2-answer' => 'Չափի կրճատումը կախված է փաստաթղթի բովանդակությունից, ինչպիսիք են պատկերները, տառատեսակները և էջի կառուցվածքը: Տեքստով ծանրաբեռնված PDF-ները սովորաբար ավելի բարձր սեղմման արագություն են ձեռք բերում, քան պատկերներով հարուստ ֆայլերը: Գործիքների մեծ մասը նվազեցնում է ֆայլի չափը 20% -ից մինչև 70%:',
  'faq3-question' => 'Արդյո՞ք PDF սեղմումն անվճար է:',
  'faq3-answer' => 'Շատ առցանց PDF սեղմման լուծումներ առաջարկում են անվճար օգտագործում՝ հիմնական հատկանիշներով և սահմանափակումներով: Անվճար տարբերակները հաճախ սահմանափակում են ամենօրյա վերբեռնումները կամ սեղմման հասանելի ուժը: Վճարովի պլանները բացում են ավելի բարձր սահմանաչափեր, ավելի արագ մշակում և առաջադեմ վերահսկում:',
  'faq4-question' => 'Արդյո՞ք PDF սեղմումն ազդում է որակի վրա:',
  'faq4-answer' => 'Սեղմումը կարող է ազդել որակի վրա՝ կախված ընտրված կարգավորումներից և փաստաթղթի տեսակից: Չափավոր սեղմումը սովորաբար պահպանում է ընթեռնելիությունը և դասավորության ճշգրտությունը: Բարձր սեղմումը կարող է նվազեցնել պատկերի հստակությունը, բայց տեքստը մաքուր է պահում:',
  'faq5-question' => 'Արդյո՞ք ֆայլերը ավտոմատ կերպով ջնջվում են PDF սեղմումից հետո:',
  'faq5-answer' => 'Շատ առցանց գործիքներ ինքնաբերաբար ջնջում են բեռնված ֆայլերը պահպանման կարճ ժամանակահատվածներից հետո: Ավտոմատ ջնջումը նվազեցնում է տվյալների բացահայտումը և բարելավում է օգտատերերի գաղտնիության պաշտպանությունը: Օգտագործողները պետք է հաստատեն ջնջման ժամկետները յուրաքանչյուր հարթակի քաղաքականության բաժնում:',
);
